import { OrderRepository, ProductRepository } from '../domain/repositories';
import { OrderDomainService } from '../domain/order-service';
import { OrderResponse } from './dtos';
import { OrderNotFoundError, InvalidStateTransitionError } from '../domain/errors';

export class CancelOrderUseCase {
  constructor(
    private orderRepo: OrderRepository,
    private productRepo: ProductRepository,
    private orderService: OrderDomainService
  ) {}

  execute(orderId: string): OrderResponse {
    const order = this.orderRepo.getById(orderId);
    if (!order) {
      throw new OrderNotFoundError(orderId);
    }

    if (order.state === 'shipped' || order.state === 'delivered') {
      throw new InvalidStateTransitionError(order.state, 'cancelled');
    }

    const reservedItems = this.orderService.releaseReservations(orderId);

    for (const reservation of reservedItems) {
      const product = this.productRepo.getById(reservation.productId);
      if (product) {
        product.stock += reservation.quantity;
        this.productRepo.save(product);
      }
    }

    order.state = 'cancelled';
    order.updatedAt = new Date();
    this.orderRepo.save(order);

    return this.mapToResponse(order);
  }

  private mapToResponse(order: any): OrderResponse {
    return {
      id: order.id,
      customerId: order.customerId,
      items: order.items,
      state: order.state,
      createdAt: order.createdAt.toISOString(),
      updatedAt: order.updatedAt.toISOString(),
    };
  }
}

