import { ProductRepository, OrderRepository } from '../domain/repositories';
import { OrderDomainService } from '../domain/order-service';
import { Order, OrderItem } from '../domain/types';
import { PlaceOrderRequest, OrderResponse } from './dtos';
import { ProductNotFoundError } from '../domain/errors';

export class PlaceOrderUseCase {
  constructor(
    private productRepo: ProductRepository,
    private orderRepo: OrderRepository,
    private orderService: OrderDomainService
  ) {}

  execute(request: PlaceOrderRequest): OrderResponse {
    const items: OrderItem[] = [];

    for (const item of request.items) {
      const product = this.productRepo.getById(item.productId);
      if (!product) {
        throw new ProductNotFoundError(item.productId);
      }
      items.push({ productId: item.productId, quantity: item.quantity, price: product.price });
    }

    const checkStock = (productId: string, quantity: number): boolean => {
      const product = this.productRepo.getById(productId);
      return product ? product.stock >= quantity : false;
    };

    const orderId = this.generateOrderId();
    this.orderService.reserveStock(orderId, items, checkStock);

    for (const item of items) {
      const product = this.productRepo.getById(item.productId);
      if (product) {
        product.stock -= item.quantity;
        this.productRepo.save(product);
      }
    }

    const order: Order = {
      id: orderId,
      customerId: request.customerId,
      items,
      state: 'placed',
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    this.orderRepo.save(order);
    return this.mapToResponse(order);
  }

  private generateOrderId(): string {
    return `ORD-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  private mapToResponse(order: Order): OrderResponse {
    return {
      id: order.id,
      customerId: order.customerId,
      items: order.items,
      state: order.state,
      createdAt: order.createdAt.toISOString(),
      updatedAt: order.updatedAt.toISOString(),
    };
  }
}

